CREATE TABLE mongodb_dataset_imports (
 id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, dataset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 requested_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, creation_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, intent VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(intent)=32),
 request JSON NOT NULL CHECK(JSON_TYPE(request)='OBJECT'), source_grant JSON NOT NULL CHECK(JSON_TYPE(source_grant)='OBJECT'), source_id LONGTEXT NOT NULL,
 state VARCHAR(16) NOT NULL CHECK(state IN('reading','exported','imported','failed')), attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 attempt_count INT NOT NULL CHECK(attempt_count BETWEEN 1 AND 20), lease_expires_at DATETIME(6), object_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 retained_objects JSON NOT NULL DEFAULT (JSON_ARRAY()) CHECK(JSON_TYPE(retained_objects)='ARRAY'),
 source_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin, source_bytes BIGINT, source_rows BIGINT, first_id VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin, last_id VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin,
 draft_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin, error_code LONGTEXT, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 UNIQUE(tenant_id,workspace_id,dataset_id,requested_by,creation_key), FOREIGN KEY(requested_by) REFERENCES users(id),
 FOREIGN KEY(tenant_id,workspace_id,dataset_id) REFERENCES datasets(tenant_id,workspace_id,id),
 FOREIGN KEY(tenant_id,workspace_id,dataset_id,draft_id) REFERENCES dataset_drafts(tenant_id,workspace_id,dataset_id,id),
 CHECK((source_sha256 IS NULL AND source_bytes IS NULL AND source_rows IS NULL AND first_id IS NULL AND last_id IS NULL) OR (source_sha256 IS NOT NULL AND source_bytes IS NOT NULL AND source_rows IS NOT NULL AND first_id IS NOT NULL AND last_id IS NOT NULL AND REGEXP_LIKE(source_sha256,'^[0-9a-f]{64}$','c') AND source_bytes>0 AND source_rows>0 AND REGEXP_LIKE(first_id,'^[0-9a-f]{24}$','c') AND REGEXP_LIKE(last_id,'^[0-9a-f]{24}$','c') AND first_id<=last_id)),
 CHECK(state NOT IN('exported','imported') OR source_sha256 IS NOT NULL), CHECK(state<>'imported' OR draft_id IS NOT NULL),
 CHECK((state IN('reading','exported') AND lease_expires_at IS NOT NULL) OR (state IN('failed','imported') AND lease_expires_at IS NULL)),
 KEY mongodb_dataset_import_lease_idx(tenant_id,lease_expires_at),
 CONSTRAINT mongoimport_id CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_tenant_id CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_workspace_id CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_dataset_id CHECK(REGEXP_LIKE(dataset_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_requested_by CHECK(REGEXP_LIKE(requested_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_creation_key CHECK(REGEXP_LIKE(creation_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_attempt_id CHECK(REGEXP_LIKE(attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_object_id CHECK(REGEXP_LIKE(object_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT mongoimport_draft_id CHECK(draft_id IS NULL OR REGEXP_LIKE(draft_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;